/** Images du kit : WebP numérotés (un fichier vide ou absent reste signalé, jamais remplacé par une autre image). */
async function loadImages(pid: string, userId: string, kind: ConversionKind, dir: string | undefined, spec: ThemeSpec) {
  const media: { role: string; file: string; asset: string }[] = [], missing: string[] = [];
  for (const role of IMAGE_ROLES[kind]) {
    const source = dir ? path.join(dir, kind === "fraise" ? "FRAISE_GUMMIES" : "ONDE_AUDIO", "images", `${role}.webp`) : "";
    if (!source || !fs.existsSync(source) || fs.statSync(source).size === 0) { missing.push(role); continue; }
    const bytes = fs.readFileSync(source), meta = await sharp(bytes).metadata();
    if (!meta.width || !meta.height || meta.width < 400) { missing.push(role); continue; }
    const file = `${kind}-${role}.webp`;
    const asset = await saveAsset({ projectId: pid, userId, data: bytes, mime: "image/webp", name: file, origin: "upload", role: "lifestyle", status: "approved", meta: { demo: { isDemo: true, provenance: DEMO_PROVENANCE }, editorialRole: role } });
    spec.files[file] = asset.id; media.push({ role, file, asset: asset.id });
  }
  return { media, missing };
}

/** Logos : SVG vectoriels (couleur pour l'en-tête, inverse pour le pied de page sombre, favicon) à partir du PNG du kit. */
async function loadLogo(pid: string, userId: string, kind: ConversionKind, dir: string | undefined, spec: ThemeSpec) {
  const source = dir ? path.join(dir, kind === "fraise" ? "FRAISE_GUMMIES" : "ONDE_AUDIO", "logos", "logo-proposition.png") : "";
  if (!source || !fs.existsSync(source)) return null;
  const palette = kind === "fraise" ? [{ name: "corail", hex: "#E4473F" }, { name: "grenat", hex: "#9E1420" }] : [{ name: "graphite", hex: "#1C1C1C" }, { name: "vert", hex: "#5EC417" }];
  const box: [number, number, number, number] = kind === "fraise" ? [0.555, 0.13, 0.665, 0.42] : [0, 0, 0.235, 1];
  const logo = await vectorizeLogo(fs.readFileSync(source), palette, box);
  const put = async (name: string, svg: string) => { const a = await saveAsset({ projectId: pid, userId, data: Buffer.from(svg), mime: "image/svg+xml", name, origin: "upload", role: "logo", status: "approved", meta: { demo: { isDemo: true, provenance: DEMO_PROVENANCE } } }); spec.files[name] = a.id; return name; };
  const files = { color: await put(`${kind}-logo.svg`, logo.color), inverse: await put(`${kind}-logo-inverse.svg`, logo.inverse), mono: await put(`${kind}-logo-mono.svg`, logo.mono), favicon: await put(`${kind}-favicon.svg`, logo.favicon) };
  const png = await saveAsset({ projectId: pid, userId, data: logo.faviconPng, mime: "image/png", name: `${kind}-favicon-180.png`, origin: "upload", role: "logo", status: "approved", meta: { demo: { isDemo: true, provenance: DEMO_PROVENANCE } } });
  spec.files[`${kind}-favicon-180.png`] = png.id;
  return { ...files, faviconPng: `${kind}-favicon-180.png`, colors: logo.colors, width: logo.width, height: logo.height };
}

